import { ELAPSED_MAX_MS, MOVES_MAX } from './game.ts';
import { parseBoardCode } from './deck.ts';
import { hasExactKeys, isJsonObject, isNonnegativeSafeInteger, isWithinBytes, parseJson } from './saved-format.ts';

export const TOURNAMENT_VERSION = 1;
export const TOURNAMENT_FILE_MAX_BYTES = 1_048_576;
export const TOURNAMENT_PLAYERS = [4, 8] as const;
export const TOURNAMENT_NAME_MAX_LENGTH = 40;
export const TOURNAMENT_HISTORY_KEY = 'neon-pairs.tournaments.v1';

export type PlayerCount = (typeof TOURNAMENT_PLAYERS)[number];
export type TournamentPhase = 'ready' | 'playing' | 'turn-complete' | 'match-complete' | 'complete';
export type Turn = 0 | 1;

export interface TournamentResult {
  readonly moves: number;
  readonly elapsedMs: number;
}

export interface TournamentMatch {
  readonly boardCode: string;
  readonly players: readonly [string | null, string | null];
  readonly results: readonly [TournamentResult | null, TournamentResult | null];
  readonly winner: string | null;
}

export interface TournamentState {
  readonly version: typeof TOURNAMENT_VERSION;
  readonly id: string;
  readonly createdAt: string;
  readonly playerCount: PlayerCount;
  readonly players: readonly string[];
  readonly rounds: readonly (readonly TournamentMatch[])[];
  readonly currentRound: number;
  readonly currentMatch: number;
  readonly turn: Turn;
  readonly phase: TournamentPhase;
  readonly champion: string | null;
}

export interface TournamentDraft {
  readonly playerCount: PlayerCount;
  readonly players: readonly string[];
}

export interface TournamentFile {
  readonly version: typeof TOURNAMENT_VERSION;
  readonly draft: TournamentDraft;
  readonly tournament: TournamentState | null;
  readonly gameSnapshot: string | null;
}

const PHASES: readonly TournamentPhase[] = [
  'ready',
  'playing',
  'turn-complete',
  'match-complete',
  'complete',
];

export function isPlayerCount(value: unknown): value is PlayerCount {
  return TOURNAMENT_PLAYERS.some((count) => count === value);
}

export function createTournament(
  players: readonly string[],
  firstBoardCode: string,
): TournamentState {
  if ((players.length !== 4 && players.length !== 8) || !validNameList(players))
    throw new Error('A tournament requires four or eight named players.');
  if (!parseBoardCode(firstBoardCode)) throw new Error('Invalid tournament board code.');

  const rounds: TournamentMatch[][] = [];
  let matchesInRound = players.length / 2;
  for (let roundIndex = 0; matchesInRound >= 1; roundIndex += 1) {
    const matches: TournamentMatch[] = [];
    for (let matchIndex = 0; matchIndex < matchesInRound; matchIndex += 1) {
      const firstRound = roundIndex === 0;
      matches.push({
        boardCode: firstRound && matchIndex === 0 ? firstBoardCode : '',
        players: firstRound
          ? [players[matchIndex * 2] ?? null, players[matchIndex * 2 + 1] ?? null]
          : [null, null],
        results: [null, null],
        winner: null,
      });
    }
    rounds.push(matches);
    matchesInRound = Math.floor(matchesInRound / 2);
  }

  return {
    version: TOURNAMENT_VERSION,
    id: crypto.randomUUID(),
    createdAt: new Date().toISOString(),
    playerCount: players.length as PlayerCount,
    players: [...players],
    rounds,
    currentRound: 0,
    currentMatch: 0,
    turn: 0,
    phase: 'ready',
    champion: null,
  };
}

export function currentTournamentMatch(tournament: TournamentState): TournamentMatch {
  const match = tournament.rounds[tournament.currentRound]?.[tournament.currentMatch];
  if (!match) throw new Error('Tournament match is out of range.');
  return match;
}

export function currentTournamentPlayer(tournament: TournamentState): string {
  const player = currentTournamentMatch(tournament).players[tournament.turn];
  if (!player) throw new Error('Tournament player is not assigned.');
  return player;
}

export function startTournamentTurn(tournament: TournamentState): TournamentState {
  if (tournament.phase !== 'ready') return tournament;
  return { ...tournament, phase: 'playing' };
}

export function recordTournamentTurn(
  tournament: TournamentState,
  result: TournamentResult,
): TournamentState {
  if (tournament.phase !== 'playing') return tournament;
  const round = tournament.rounds[tournament.currentRound];
  const match = round?.[tournament.currentMatch];
  if (!round || !match || match.results[tournament.turn]) return tournament;
  const results: [TournamentResult | null, TournamentResult | null] = [...match.results];
  results[tournament.turn] = {
    moves: Math.min(MOVES_MAX, Math.max(0, Math.floor(result.moves))),
    elapsedMs: Math.min(ELAPSED_MAX_MS, Math.max(0, Math.floor(result.elapsedMs))),
  };
  const bothComplete = results[0] !== null && results[1] !== null;
  const winner = bothComplete
    ? decideWinner(match.players, results)
    : null;
  const updatedMatch: TournamentMatch = { ...match, results, winner };
  const rounds = replaceMatch(tournament.rounds, tournament.currentRound, tournament.currentMatch, updatedMatch);
  const isFinalMatch =
    tournament.currentRound === rounds.length - 1 && tournament.currentMatch === 0;

  if (tournament.turn === 0) {
    return { ...tournament, rounds, phase: 'turn-complete' };
  }
  if (isFinalMatch) return { ...tournament, rounds, phase: 'complete', champion: winner };
  return { ...tournament, rounds, phase: 'match-complete' };
}

export function advanceTournamentTurn(tournament: TournamentState): TournamentState {
  if (tournament.phase !== 'turn-complete') return tournament;
  return { ...tournament, turn: 1, phase: 'ready' };
}

export function advanceTournamentMatch(
  tournament: TournamentState,
  nextBoardCode: string,
): TournamentState {
  if (tournament.phase !== 'match-complete' || !parseBoardCode(nextBoardCode)) return tournament;
  let currentRound = tournament.currentRound;
  let currentMatch = tournament.currentMatch + 1;
  const rounds = tournament.rounds.map((round) => [...round]);
  if (currentMatch >= (rounds[currentRound]?.length ?? 0)) {
    const previousRound = rounds[currentRound];
    if (!previousRound || currentRound + 1 >= rounds.length) return tournament;
    currentRound += 1;
    currentMatch = 0;
    const nextRound = rounds[currentRound];
    if (!nextRound) return tournament;
    for (let index = 0; index < nextRound.length; index += 1) {
      const first = previousRound[index * 2]?.winner ?? null;
      const second = previousRound[index * 2 + 1]?.winner ?? null;
      nextRound[index] = { ...nextRound[index]!, players: [first, second] };
    }
  }
  const match = rounds[currentRound]?.[currentMatch];
  if (!match || !match.players[0] || !match.players[1]) return tournament;
  rounds[currentRound]![currentMatch] = { ...match, boardCode: nextBoardCode };
  return {
    ...tournament,
    rounds,
    currentRound,
    currentMatch,
    turn: 0,
    phase: 'ready',
    champion: null,
  };
}

export function decideWinner(
  players: readonly [string | null, string | null],
  results: readonly [TournamentResult | null, TournamentResult | null],
): string | null {
  const firstPlayer = players[0];
  const secondPlayer = players[1];
  const first = results[0];
  const second = results[1];
  if (!firstPlayer || !secondPlayer || !first || !second) return null;
  if (first.moves !== second.moves) return first.moves < second.moves ? firstPlayer : secondPlayer;
  if (first.elapsedMs !== second.elapsedMs)
    return first.elapsedMs < second.elapsedMs ? firstPlayer : secondPlayer;
  return firstPlayer;
}

export function decodeTournamentFile(text: string): TournamentFile | null {
  if (!isWithinBytes(text, TOURNAMENT_FILE_MAX_BYTES)) return null;
  const value = parseJson(text);
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['version', 'draft', 'tournament', 'gameSnapshot']) ||
    value.version !== TOURNAMENT_VERSION ||
    !isJsonObject(value.draft) ||
    !hasExactKeys(value.draft, ['playerCount', 'players']) ||
    !isPlayerCount(value.draft.playerCount) ||
    !isDraftPlayers(value.draft.players)
  )
    return null;
  const tournament = value.tournament === null ? null : decodeTournamentValue(value.tournament);
  if (value.tournament !== null && !tournament) return null;
  if (value.gameSnapshot !== null && typeof value.gameSnapshot !== 'string') return null;
  return {
    version: TOURNAMENT_VERSION,
    draft: { playerCount: value.draft.playerCount, players: [...value.draft.players] },
    tournament,
    gameSnapshot: value.gameSnapshot,
  };
}

export function decodeTournamentValue(value: unknown): TournamentState | null {
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, [
      'version',
      'id',
      'createdAt',
      'playerCount',
      'players',
      'rounds',
      'currentRound',
      'currentMatch',
      'turn',
      'phase',
      'champion',
    ]) ||
    value.version !== TOURNAMENT_VERSION ||
    typeof value.id !== 'string' ||
    value.id.length < 1 ||
    value.id.length > 100 ||
    typeof value.createdAt !== 'string' ||
    !Number.isFinite(Date.parse(value.createdAt)) ||
    !isPlayerCount(value.playerCount) ||
    !validNameList(value.players) ||
    value.players.length !== value.playerCount ||
    !Array.isArray(value.rounds) ||
    !isNonnegativeSafeInteger(value.currentRound) ||
    !isNonnegativeSafeInteger(value.currentMatch) ||
    (value.turn !== 0 && value.turn !== 1) ||
    typeof value.phase !== 'string' ||
    !PHASES.includes(value.phase as TournamentPhase) ||
    (value.champion !== null && !isTournamentName(value.champion))
  )
    return null;

  const playerCount = value.playerCount;
  const expectedRoundCount = Math.log2(playerCount);
  if (value.rounds.length !== expectedRoundCount) return null;
  const rounds: TournamentMatch[][] = [];
  let expectedMatchCount = playerCount / 2;
  for (let roundIndex = 0; roundIndex < value.rounds.length; roundIndex += 1) {
    const roundValue = value.rounds[roundIndex];
    if (!Array.isArray(roundValue) || roundValue.length !== expectedMatchCount) return null;
    const round: TournamentMatch[] = [];
    for (let matchIndex = 0; matchIndex < roundValue.length; matchIndex += 1) {
      const match = decodeMatch(roundValue[matchIndex]);
      if (!match) return null;
      if (roundIndex === 0) {
        if (
          match.players[0] !== value.players[matchIndex * 2] ||
          match.players[1] !== value.players[matchIndex * 2 + 1]
        )
          return null;
      } else {
        const previousRound = rounds[roundIndex - 1];
        const firstWinner = previousRound?.[matchIndex * 2]?.winner ?? null;
        const secondWinner = previousRound?.[matchIndex * 2 + 1]?.winner ?? null;
        const bothWinnersKnown = firstWinner !== null && secondWinner !== null;
        if (
          (bothWinnersKnown &&
            (match.players[0] !== firstWinner || match.players[1] !== secondWinner)) ||
          (!bothWinnersKnown && (match.players[0] !== null || match.players[1] !== null))
        )
          return null;
      }
      round.push(match);
    }
    rounds.push(round);
    expectedMatchCount /= 2;
  }

  if (value.currentRound >= rounds.length || value.currentMatch >= (rounds[value.currentRound]?.length ?? 0))
    return null;
  const state: TournamentState = {
    version: TOURNAMENT_VERSION,
    id: value.id,
    createdAt: value.createdAt,
    playerCount,
    players: [...value.players],
    rounds,
    currentRound: value.currentRound,
    currentMatch: value.currentMatch,
    turn: value.turn,
    phase: value.phase as TournamentPhase,
    champion: value.champion,
  };
  const current = currentTournamentMatch(state);
  if (!parseBoardCode(current.boardCode) || !current.players[0] || !current.players[1]) return null;

  const phaseValid =
    (state.phase === 'ready' && current.results[state.turn] === null && state.champion === null) ||
    (state.phase === 'playing' && current.results[state.turn] === null && state.champion === null) ||
    (state.phase === 'turn-complete' &&
      state.turn === 0 &&
      current.results[0] !== null &&
      current.results[1] === null &&
      state.champion === null) ||
    (state.phase === 'match-complete' &&
      state.turn === 1 &&
      current.results[0] !== null &&
      current.results[1] !== null &&
      current.winner !== null &&
      state.currentRound < rounds.length - 1 &&
      state.champion === null) ||
    (state.phase === 'complete' &&
      state.currentRound === rounds.length - 1 &&
      state.currentMatch === 0 &&
      current.results[0] !== null &&
      current.results[1] !== null &&
      current.winner === state.champion &&
      state.champion !== null);
  if (!phaseValid) return null;
  return state;
}

export function decodePastTournaments(text: string): TournamentState[] {
  if (!isWithinBytes(text, TOURNAMENT_FILE_MAX_BYTES * 5)) return [];
  const value = parseJson(text);
  if (!Array.isArray(value)) return [];
  const tournaments: TournamentState[] = [];
  const seen = new Set<string>();
  for (const item of value) {
    const tournament = decodeTournamentValue(item);
    if (tournament?.phase === 'complete' && !seen.has(tournament.id)) {
      seen.add(tournament.id);
      tournaments.push(tournament);
    }
  }
  return tournaments;
}

function decodeMatch(value: unknown): TournamentMatch | null {
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['boardCode', 'players', 'results', 'winner']) ||
    typeof value.boardCode !== 'string' ||
    (value.boardCode !== '' && !parseBoardCode(value.boardCode)) ||
    !Array.isArray(value.players) ||
    value.players.length !== 2 ||
    !value.players.every((player) => player === null || isTournamentName(player)) ||
    !Array.isArray(value.results) ||
    value.results.length !== 2 ||
    (value.winner !== null && !isTournamentName(value.winner))
  )
    return null;
  const players: [string | null, string | null] = [value.players[0], value.players[1]];
  const results: [TournamentResult | null, TournamentResult | null] = [
    decodeResult(value.results[0], value.boardCode),
    decodeResult(value.results[1], value.boardCode),
  ];
  if (
    (value.results[0] !== null && !results[0]) ||
    (value.results[1] !== null && !results[1]) ||
    ((results[0] || results[1]) && (!players[0] || !players[1]))
  )
    return null;
  const winner = value.winner as string | null;
  const expectedWinner = decideWinner(players, results);
  if ((winner !== null && winner !== expectedWinner) || (results[0] && results[1] && !winner))
    return null;
  if ((winner || results[0] || results[1]) && !parseBoardCode(value.boardCode)) return null;
  return { boardCode: value.boardCode, players, results, winner };
}

function decodeResult(value: unknown, boardCode: string): TournamentResult | null {
  if (value === null) return null;
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['moves', 'elapsedMs']) ||
    !isNonnegativeSafeInteger(value.moves) ||
    value.moves > MOVES_MAX ||
    !isNonnegativeSafeInteger(value.elapsedMs) ||
    value.elapsedMs > ELAPSED_MAX_MS
  )
    return null;
  const board = parseBoardCode(boardCode);
  if (!board || value.moves < (board.size * board.size) / 2) return null;
  return { moves: value.moves, elapsedMs: value.elapsedMs };
}

function validNameList(value: unknown): value is readonly string[] {
  return Array.isArray(value) && value.every(isTournamentName);
}

function isDraftPlayers(value: unknown): value is readonly string[] {
  return (
    Array.isArray(value) &&
    value.length === 8 &&
    value.every((name) => typeof name === 'string' && name.length <= TOURNAMENT_NAME_MAX_LENGTH)
  );
}

function isTournamentName(value: unknown): value is string {
  return (
    typeof value === 'string' &&
    value.length > 0 &&
    value.length <= TOURNAMENT_NAME_MAX_LENGTH &&
    value === value.trim()
  );
}

function replaceMatch(
  rounds: readonly (readonly TournamentMatch[])[],
  roundIndex: number,
  matchIndex: number,
  match: TournamentMatch,
): TournamentMatch[][] {
  return rounds.map((round, index) =>
    index === roundIndex ? round.map((entry, entryIndex) => (entryIndex === matchIndex ? match : entry)) : [...round],
  );
}

import { useRef, useState } from 'react';
import { Board } from './board/Board.tsx';
import { Controls } from './controls/Controls.tsx';
import { Reproduction } from './controls/Reproduction.tsx';
import { GameStatus } from './status/GameStatus.tsx';
import { Tournament } from './Tournament.tsx';
import type { BoardFocus } from './board/Board.tsx';
import { useGame } from './session/use-game.ts';
import './game.css';

export function Game() {
  const controller = useGame();
  const { session } = controller;
  const { game } = session;
  const board = useRef<BoardFocus>(null);
  const [tournamentOpen, setTournamentOpen] = useState(false);
  const suspendedGame = useRef<{ snapshot: string; paused: boolean } | null>(null);
  function resume(): void {
    board.current?.focusRemembered();
    controller.resume();
  }
  function openTournament(): void {
    suspendedGame.current = {
      snapshot: controller.exportSnapshot(),
      paused: controller.session.paused,
    };
    controller.pause();
    setTournamentOpen(true);
  }
  function closeTournament(): void {
    const saved = suspendedGame.current;
    if (saved && controller.loadSnapshot(saved.snapshot) && !saved.paused) controller.resume();
    suspendedGame.current = null;
    setTournamentOpen(false);
  }
  return (
    <main>
      <header>
        <p className="eyebrow">A little focus. A perfect pair.</p>
        <h1>Neon Pairs</h1>
      </header>
      {tournamentOpen ? (
        <Tournament
          game={game}
          feedback={session.feedback}
          announcement={session.announcement}
          activate={controller.activate}
          exportSnapshot={controller.exportSnapshot}
          loadBoard={controller.loadBoard}
          loadSnapshot={controller.loadSnapshot}
          resume={controller.resume}
          leave={closeTournament}
          backToGame={closeTournament}
        />
      ) : (
        <>
          <p className="intro">Reveal two cards. Match their shape and marker to keep the pair.</p>
          <Controls
            size={game.size}
            newGame={controller.newGame}
            restart={controller.restart}
            openTournament={openTournament}
          />
          <GameStatus
            game={game}
            best={session.preferences.bestMoves[String(game.size)]}
            celebration={session.celebration}
          />
          <p id="board-help" className="help">
            Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space
            reveals a card.
          </p>
          <div className="game-result">
            <p role="status" aria-live="polite" aria-atomic="true">
              <span key={session.announcement}>{session.feedback}</span>
            </p>
          </div>
          <Board key={session.generation} game={game} activate={controller.activate} ref={board} />
          <Reproduction
            game={game}
            generation={session.generation}
            exportSnapshot={controller.exportSnapshot}
            loadBoard={controller.loadBoard}
            loadSnapshot={controller.loadSnapshot}
            notice={session.loadNotice}
            paused={session.paused}
            resume={resume}
          />
        </>
      )}
    </main>
  );
}
import { useRef, useState } from 'react';
import { createGame } from '../game.ts';
import { parseBoardCode, isValidSize } from '../deck.ts';
import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts';
import { freshBoardCode } from './fresh-board.ts';
import { activateSession, initialSession, replaceGame, SessionNotice } from './session.ts';
import { readPreferences } from './storage.ts';
import { browserStore, useSavedPreferences } from './use-saved-preferences.ts';
import { useSessionClock } from './use-session-clock.ts';
import type { Session } from './session.ts';

export function useGame() {
  const [store] = useState(browserStore);
  const [session, setSession] = useState(() => {
    const preferences = readPreferences(store);
    return initialSession(freshBoardCode(preferences.size), preferences);
  });
  const current = useRef(session);

  function commit(next: Session): void {
    if (next === current.current) return;
    current.current = next;
    setSession(next);
  }

  const clock = useSessionClock(session, current, commit);
  useSavedPreferences(store, session.preferences);

  function newGame(size = current.current.game.size): void {
    if (!isValidSize(size)) return;
    const next = createGame(freshBoardCode(size, current.current.game.seed));
    clock.reset();
    commit(replaceGame(current.current, next, false));
  }

  function restart(): void {
    clock.reset();
    commit(replaceGame(current.current, createGame(current.current.game.boardCode), false));
  }

  function notice(feedback: string): void {
    commit({
      ...current.current,
      feedback,
      loadNotice: feedback,
      announcement: current.current.announcement + 1,
    });
  }

  function loadBoard(code: string): boolean {
    code = code.trim();
    if (!parseBoardCode(code)) {
      notice(SessionNotice.invalidBoard);
      return false;
    }
    clock.reset();
    commit(replaceGame(current.current, createGame(code), false));
    return true;
  }

  function loadSnapshot(text: string): boolean {
    const game = decodeSnapshot(text);
    if (!game) {
      notice(SessionNotice.invalidSnapshot);
      return false;
    }
    clock.reset();
    commit(replaceGame(current.current, game, true));
    return true;
  }

  function exportSnapshot(): string {
    // Rendered state can trail the active clock by a tick.
    clock.synchronize();
    return encodeSnapshot(current.current.game);
  }

  function activate(index: number): void {
    clock.synchronize();
    commit(activateSession(current.current, index));
  }

  function resume(): void {
    clock.reset();
    commit({
      ...current.current,
      paused: false,
      feedback: '',
      loadNotice: '',
    });
  }

  function pause(): void {
    if (current.current.paused) return;
    clock.synchronize();
    commit({ ...current.current, paused: true });
  }

  return {
    session,
    newGame,
    restart,
    loadBoard,
    loadSnapshot,
    exportSnapshot,
    activate,
    resume,
    pause,
  };
}

import { useEffect, useRef, useState } from 'react';
import { isWon } from './game.ts';
import type { GameState } from './game.ts';
import { parseBoardCode } from './deck.ts';
import { Board } from './board/Board.tsx';
import type { BoardFocus } from './board/Board.tsx';
import { decodeSnapshot } from './snapshot.ts';
import { formatElapsed } from './elapsed-time.ts';
import { freshBoardCode } from './session/fresh-board.ts';
import { readPastTournaments, writePastTournaments } from './tournament-storage.ts';
import {
  TOURNAMENT_FILE_MAX_BYTES,
  TOURNAMENT_NAME_MAX_LENGTH,
  TOURNAMENT_VERSION,
  advanceTournamentMatch,
  advanceTournamentTurn,
  createTournament,
  currentTournamentMatch,
  currentTournamentPlayer,
  decodeTournamentFile,
  recordTournamentTurn,
  startTournamentTurn,
} from './tournament.ts';
import type { PlayerCount, TournamentMatch, TournamentResult, TournamentState } from './tournament.ts';
import './tournament.css';

interface TournamentProps {
  game: GameState;
  feedback: string;
  announcement: number;
  activate(index: number): void;
  exportSnapshot(): string;
  loadBoard(code: string): boolean;
  loadSnapshot(text: string): boolean;
  resume(): void;
  leave(): void;
  backToGame(): void;
}

const EMPTY_NAMES = Array.from({ length: 8 }, () => '');

export function Tournament({
  game,
  feedback,
  announcement,
  activate,
  exportSnapshot,
  loadBoard,
  loadSnapshot,
  resume,
  leave,
  backToGame,
}: TournamentProps) {
  const [playerCount, setPlayerCount] = useState<PlayerCount>(4);
  const [names, setNames] = useState<string[]>(() => [...EMPTY_NAMES]);
  const [tournament, setTournament] = useState<TournamentState | null>(null);
  const [past, setPast] = useState(readPastTournaments);
  const [json, setJson] = useState('');
  const [notice, setNotice] = useState('');
  const board = useRef<BoardFocus>(null);
  const activePhase = tournament?.phase;

  useEffect(() => writePastTournaments(past), [past]);

  useEffect(() => {
    if (!tournament || tournament.phase !== 'playing') return;
    const match = currentTournamentMatch(tournament);
    if (!isWon(game) || game.boardCode !== match.boardCode) return;
    const result: TournamentResult = { moves: game.moves, elapsedMs: game.elapsedMs };
    setTournament((current) => (current ? recordTournamentTurn(current, result) : current));
  }, [game, tournament]);

  useEffect(() => {
    if (tournament?.phase !== 'complete') return;
    setPast((current) =>
      current.some((entry) => entry.id === tournament.id) ? current : [tournament, ...current],
    );
  }, [tournament]);

  useEffect(() => {
    if (activePhase === 'playing') board.current?.focusRemembered();
  }, [activePhase]);

  function updateName(index: number, value: string): void {
    setNames((current) => current.map((name, entryIndex) => (entryIndex === index ? value : name)));
  }

  function start(): void {
    const players = names
      .slice(0, playerCount)
      .map((name, index) => name.trim().slice(0, TOURNAMENT_NAME_MAX_LENGTH) || `Player ${index + 1}`);
    const initial = createTournament(players, freshBoardCode(game.size, game.seed));
    setTournament(initial);
    setNotice('');
  }

  function startTurn(): void {
    if (!tournament || tournament.phase !== 'ready') return;
    const match = currentTournamentMatch(tournament);
    if (!loadBoard(match.boardCode)) {
      setNotice('Could not start this tournament turn.');
      return;
    }
    setTournament(startTournamentTurn(tournament));
    setNotice('');
  }

  function nextTurn(): void {
    if (!tournament || tournament.phase !== 'turn-complete') return;
    const match = currentTournamentMatch(tournament);
    if (!loadBoard(match.boardCode)) {
      setNotice('Could not prepare the next turn.');
      return;
    }
    setTournament(advanceTournamentTurn(tournament));
    setNotice('');
  }

  function nextMatch(): void {
    if (!tournament || tournament.phase !== 'match-complete') return;
    const previousMatch = currentTournamentMatch(tournament);
    const previousSeed = parseBoardCode(previousMatch.boardCode)?.seed;
    const nextCode = freshBoardCode(game.size, previousSeed);
    const next = advanceTournamentMatch(tournament, nextCode);
    if (next === tournament) return;
    const match = currentTournamentMatch(next);
    if (!loadBoard(match.boardCode)) {
      setNotice('Could not prepare the next match.');
      return;
    }
    setTournament(next);
    setNotice('');
  }

  function exportTournament(): void {
    const saved = tournament ?? past[0] ?? null;
    const draftCount = tournament?.playerCount ?? playerCount;
    const draftNames = tournament
      ? [...tournament.players, ...Array.from({ length: 8 - tournament.players.length }, () => '')]
      : names;
    const match = tournament ? currentTournamentMatch(tournament) : null;
    const snapshot =
      tournament && match?.boardCode === game.boardCode ? exportSnapshot() : null;
    setJson(
      JSON.stringify(
        {
          version: TOURNAMENT_VERSION,
          draft: { playerCount: draftCount, players: draftNames },
          tournament: saved,
          gameSnapshot: snapshot,
        },
        null,
        2,
      ),
    );
    setNotice('Tournament JSON exported.');
  }

  function loadTournament(): void {
    const file = decodeTournamentFile(json);
    if (!file) {
      setNotice('Invalid tournament JSON.');
      return;
    }
    const savedTournament = file.tournament;
    const savedGame = file.gameSnapshot === null ? null : decodeSnapshot(file.gameSnapshot);
    if (
      (file.gameSnapshot !== null && !savedGame) ||
      (!savedTournament && savedGame) ||
      (savedTournament &&
        savedGame &&
        savedGame.boardCode !== currentTournamentMatch(savedTournament).boardCode)
    ) {
      setNotice('Invalid tournament JSON.');
      return;
    }

    let loadedTournament = savedTournament;
    if (loadedTournament?.phase === 'playing' && !savedGame) {
      loadedTournament = { ...loadedTournament, phase: 'ready' };
    }
    if (loadedTournament?.phase === 'playing' && savedGame) {
      if (!loadSnapshot(file.gameSnapshot!)) {
        setNotice('Invalid tournament JSON.');
        return;
      }
      resume();
    } else if (loadedTournament?.phase === 'ready') {
      if (!loadBoard(currentTournamentMatch(loadedTournament).boardCode)) {
        setNotice('Invalid tournament JSON.');
        return;
      }
    }

    setPlayerCount(file.draft.playerCount);
    setNames([...file.draft.players]);
    setTournament(loadedTournament);
    setNotice('Tournament loaded.');
  }

  const currentMatch = tournament ? currentTournamentMatch(tournament) : null;
  const nowPlaying = tournament && tournament.phase !== 'complete' && tournament.phase !== 'match-complete'
    ? currentTournamentPlayer(tournament)
    : null;
  const visibleBoard =
    tournament?.phase === 'playing' && currentMatch?.boardCode === game.boardCode;

  return (
    <section className="tournament-screen" aria-labelledby="tournament-title">
      <h2 id="tournament-title">Tournament</h2>
      <p className="tournament-intro">
        A knockout tournament for one device. Players take turns on the same deal; fewer moves wins.
        If moves tie, the faster time wins.
      </p>

      {!tournament ? (
        <section className="tournament-setup" aria-labelledby="setup-title">
          <h3 id="setup-title">Set up a tournament</h3>
          <div className="tournament-count">
            <label htmlFor="tournament-player-count">Players</label>
            <select
              id="tournament-player-count"
              className="control"
              value={playerCount}
              onChange={(event) => setPlayerCount(Number(event.currentTarget.value) as PlayerCount)}
            >
              <option value={4}>4</option>
              <option value={8}>8</option>
            </select>
          </div>
          <div className="tournament-name-grid">
            {names.map((name, index) => (
              <div className="tournament-name" key={index}>
                <label htmlFor={`tournament-player-${index + 1}`}>Player {index + 1}</label>
                <input
                  id={`tournament-player-${index + 1}`}
                  className="control"
                  type="text"
                  maxLength={TOURNAMENT_NAME_MAX_LENGTH}
                  value={name}
                  placeholder={`Player ${index + 1}`}
                  onChange={(event) => updateName(index, event.currentTarget.value)}
                />
              </div>
            ))}
          </div>
          <div className="tournament-actions">
            <button type="button" className="control" onClick={start}>
              Start tournament
            </button>
            <button type="button" className="control" onClick={leave}>
              Leave tournament
            </button>
          </div>
        </section>
      ) : (
        <>
          <section className="tournament-current" aria-labelledby="current-match-title">
            <h3 id="current-match-title">
              {tournament.phase === 'complete'
                ? 'Tournament complete'
                : `Match ${tournament.currentMatch + 1} · ${roundTitle(tournament.currentRound, tournament.rounds.length)}`}
            </h3>
            {nowPlaying && <p className="now-playing">Now playing: {nowPlaying}</p>}
            {tournament.phase === 'match-complete' && currentMatch?.winner && (
              <p className="match-winner">Winner: {currentMatch.winner}</p>
            )}
            {tournament.phase === 'ready' && (
              <button type="button" className="control" onClick={startTurn}>
                Start turn
              </button>
            )}
            {tournament.phase === 'playing' && (
              <>
                <dl className="tournament-stats" aria-label="Current turn statistics">
                  <div>
                    <dt>Moves</dt>
                    <dd>{game.moves}</dd>
                  </div>
                  <div>
                    <dt>Time</dt>
                    <dd>{formatElapsed(game.elapsedMs)}</dd>
                  </div>
                </dl>
                <p id="tournament-board-help" className="help">
                  Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or
                  Space reveals a card.
                </p>
                <div className="game-result">
                  <p role="status" aria-live="polite" aria-atomic="true">
                    <span key={announcement}>{feedback}</span>
                  </p>
                </div>
                {visibleBoard && <Board game={game} activate={activate} ref={board} />}
              </>
            )}
            {tournament.phase === 'turn-complete' && (
              <div className="tournament-actions">
                <p>
                  {currentMatch?.players[0]} finished with {currentMatch?.results[0]?.moves} moves in{' '}
                  {formatElapsed(currentMatch?.results[0]?.elapsedMs ?? 0)}.
                </p>
                <button type="button" className="control" onClick={nextTurn}>
                  Next turn
                </button>
              </div>
            )}
            {tournament.phase === 'match-complete' && (
              <div className="tournament-actions">
                <button type="button" className="control" onClick={nextMatch}>
                  Next match
                </button>
                <button type="button" className="control" onClick={leave}>
                  Leave tournament
                </button>
              </div>
            )}
            {tournament.phase === 'complete' && (
              <>
                <p className="champion">Champion: {tournament.champion}</p>
                <button type="button" className="control" onClick={backToGame}>
                  Back to game
                </button>
              </>
            )}
            {tournament.phase !== 'complete' && tournament.phase !== 'match-complete' && (
              <button type="button" className="control tournament-leave" onClick={leave}>
                Leave tournament
              </button>
            )}
          </section>
          <TournamentBracket tournament={tournament} game={game} />
        </>
      )}

      <section className="tournament-transfer" aria-labelledby="tournament-json-title">
        <h3 id="tournament-json-title">Tournament JSON</h3>
        <label htmlFor="tournament-json">Tournament JSON</label>
        <textarea
          id="tournament-json"
          className="control"
          rows={8}
          maxLength={TOURNAMENT_FILE_MAX_BYTES}
          spellCheck={false}
          value={json}
          onChange={(event) => setJson(event.currentTarget.value)}
        />
        <div className="tournament-actions">
          <button type="button" className="control" onClick={exportTournament}>
            Export tournament
          </button>
          <button type="button" className="control" onClick={loadTournament}>
            Load tournament
          </button>
        </div>
        <p className="tournament-notice" role="status" aria-live="polite">
          {notice}
        </p>
      </section>

      <section className="tournament-past" aria-labelledby="past-tournaments-title">
        <h3 id="past-tournaments-title">Past tournaments</h3>
        {past.length === 0 ? (
          <p>No completed tournaments yet.</p>
        ) : (
          <ol>
            {past.map((entry) => (
              <li key={entry.id}>
                <strong>Champion: {entry.champion}</strong>
                <span>
                  {entry.playerCount} players · {new Date(entry.createdAt).toLocaleDateString()}
                </span>
              </li>
            ))}
          </ol>
        )}
      </section>
    </section>
  );
}

interface BracketProps {
  tournament: TournamentState;
  game: GameState;
}

function TournamentBracket({ tournament, game }: BracketProps) {
  return (
    <section className="tournament-bracket" aria-labelledby="bracket-title">
      <h3 id="bracket-title">Bracket</h3>
      <p className="bracket-rule">Fewer moves wins. Time breaks a tie.</p>
      <div className="bracket-rounds">
        {tournament.rounds.map((round, roundIndex) => (
          <section className="bracket-round" key={roundIndex} aria-label={roundTitle(roundIndex, tournament.rounds.length)}>
            <h4>{roundTitle(roundIndex, tournament.rounds.length)}</h4>
            <ol>
              {round.map((match, matchIndex) => (
                <li className="bracket-match" key={`${roundIndex}-${matchIndex}`}>
                  <h5>Match {matchIndex + 1}</h5>
                  {[0, 1].map((slot) => {
                    const result = visibleResult(tournament, match, roundIndex, matchIndex, slot as 0 | 1, game);
                    const isCurrent =
                      tournament.phase === 'playing' &&
                      tournament.currentRound === roundIndex &&
                      tournament.currentMatch === matchIndex &&
                      tournament.turn === slot &&
                      game.boardCode === match.boardCode &&
                      !match.results[slot as 0 | 1];
                    return (
                      <p className={`bracket-player${match.winner === match.players[slot] ? ' is-winner' : ''}`} key={slot}>
                        <span>{match.players[slot] ?? 'TBD'}</span>
                        <span>
                          {result ? `${result.moves} moves · ${formatElapsed(result.elapsedMs)}` : '—'}
                          {isCurrent ? ' · current' : ''}
                        </span>
                      </p>
                    );
                  })}
                  <p className="bracket-winner">Winner: {match.winner ?? '—'}</p>
                </li>
              ))}
            </ol>
          </section>
        ))}
      </div>
    </section>
  );
}

function visibleResult(
  tournament: TournamentState,
  match: TournamentMatch,
  roundIndex: number,
  matchIndex: number,
  slot: 0 | 1,
  game: GameState,
): TournamentResult | null {
  const saved = match.results[slot];
  if (saved) return saved;
  if (
    tournament.phase === 'playing' &&
    tournament.currentRound === roundIndex &&
    tournament.currentMatch === matchIndex &&
    tournament.turn === slot &&
    game.boardCode === match.boardCode
  )
    return { moves: game.moves, elapsedMs: game.elapsedMs };
  return null;
}

