.tournament-screen h4,
.tournament-screen h5 {
  font-size: 16px;
  line-height: 24px;
  margin: 0;
}
.tournament-intro {
  max-width: 72ch;
  color: var(--secondary);
  margin-bottom: 24px;
}
.tournament-setup,
.tournament-current,
.tournament-transfer,
.tournament-past,
.tournament-bracket {
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--panel);
  padding: 16px;
  margin-bottom: 16px;
}
.tournament-count {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 16px;
}
.tournament-count select {
  min-width: 100px;
}
.tournament-name-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 220px), 1fr));
  gap: 12px;
}
.tournament-name {
  display: grid;
  gap: 6px;
}
.tournament-name input {
  width: 100%;
}
.tournament-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 16px;
}
.now-playing,
.match-winner,
.champion {
  font-size: 18px;
  margin-bottom: 12px;
}
.now-playing {
  color: var(--green);
  font-weight: 700;
}
.champion {
  font-size: 24px;
  font-weight: 700;
  color: var(--green);
}
.tournament-leave {
  margin-top: 16px;
}
.tournament-stats {
  display: flex;
  flex-wrap: wrap;
  gap: 12px 24px;
  margin: 8px 0 12px;
}
.tournament-stats div {
  min-width: 8ch;
}
.tournament-transfer h3 {
  margin-bottom: 6px;
}
.tournament-transfer label {
  display: block;
  margin-bottom: 6px;
}
.tournament-transfer textarea {
  width: 100%;
  resize: vertical;
  font-family: ui-monospace, monospace;
  font-size: 14px;
}
.tournament-notice {
  min-height: 24px;
  color: var(--secondary);
  margin-top: 8px;
}
.bracket-rule {
  color: var(--secondary);
  margin: -6px 0 12px;
}
.bracket-rounds {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 240px), 1fr));
  gap: 12px;
}
.bracket-round h4 {
  margin-bottom: 8px;
}
.bracket-round ol {
  display: grid;
  gap: 8px;
  list-style: none;
  padding: 0;
  margin: 0;
}
.bracket-match {
  padding: 8px 12px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--face);
}
.bracket-match h5 {
  color: var(--secondary);
  margin-bottom: 6px;
}
.bracket-player {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px;
  padding: 4px 0;
}
.bracket-player span:first-child {
  min-width: 0;
  overflow-wrap: anywhere;
}
.bracket-player span:last-child {
  flex: none;
  color: var(--secondary);
  font-size: 14px;
  font-variant-numeric: tabular-nums;
}
.bracket-player.is-winner span:first-child {
  color: var(--green);
  font-weight: 700;
}
.bracket-winner {
  border-top: 1px solid var(--border);
  margin-top: 4px;
  padding-top: 6px;
  font-weight: 700;
}
.tournament-past ol {
  display: grid;
  gap: 8px;
  list-style: none;
  padding: 0;
  margin: 0;
}
.tournament-past li {
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 4px 16px;
  padding: 8px 0;
  border-bottom: 1px solid var(--border);
}
.tournament-past li:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}
.tournament-past li span {
  color: var(--secondary);
}
.past-tournament-entry {
  width: 100%;
}
.past-tournament-entry > summary {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 4px 16px;
  min-height: 44px;
  cursor: pointer;
}
.past-tournament-entry .tournament-bracket {
  margin: 8px 0 0;
}
@media (max-width: 599px) {
  .tournament-setup,
  .tournament-current,
  .tournament-transfer,
  .tournament-past,
  .tournament-bracket {
    padding: 12px;
  }
  .tournament-actions > button {
    flex: 1 1 auto;
  }
}

import { useCallback, useRef, useState } from 'react';
import { navigationTarget } from './keyboard.ts';
import { useNearestScroll } from './nearest-scroll.ts';
import type { KeyboardEvent } from 'react';

const KEYBOARD_FOCUS = ':focus-visible';

// Keeps the board's remembered tab stop, moves focus with the arrow keys and scrolls keyboard
// focus into view with nearest alignment.
export function useBoardFocus(size: number) {
  const viewport = useRef<HTMLDivElement>(null);
  const element = useRef<HTMLDivElement>(null);
  const [focused, setFocused] = useState(0);
  const scrollToNearest = useNearestScroll(viewport);
  // Focus calls skip the browser's centering scroll and then scroll with nearest alignment.
  const focusRemembered = useCallback(() => {
    const card = element.current?.querySelectorAll('button').item(focused);
    card?.focus({ preventScroll: true });
    if (card) scrollToNearest(card);
  }, [focused, scrollToNearest]);
  const navigate = useCallback(
    (event: KeyboardEvent<HTMLButtonElement>, index: number): void => {
      const target = navigationTarget(index, size, event.key, event);
      if (target === null) return;
      event.preventDefault();
      const card = element.current?.querySelectorAll('button').item(target);
      card?.focus({ preventScroll: true });
    },
    [size],
  );
  const cardFocused = useCallback(
    (index: number, card: HTMLElement): void => {
      setFocused(index);
      // Moving a card under a pressed pointer would send the release elsewhere and lose the click.
      if (card.matches(KEYBOARD_FOCUS)) scrollToNearest(card);
    },
    [scrollToNearest],
  );
  return { viewport, element, focused, focusRemembered, navigate, cardFocused };
}
import { useEffect } from 'react';
import { writePreferences } from './storage.ts';
import type { Preferences, PreferenceStore } from './storage.ts';

// Reading localStorage can throw when the browser blocks storage, and play continues without it.
export function browserStore(): PreferenceStore | null {
  try {
    return window.localStorage;
  } catch {
    return null;
  }
}

// Saves this tab's size and bests after each change.
export function useSavedPreferences(store: PreferenceStore | null, preferences: Preferences) {
  useEffect(() => {
    writePreferences(store, preferences);
  }, [preferences, store]);
}
